contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        uint256 ownerBalanceBefore = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;
        require(amount <= ownerBalanceBefore, "burn exceeds owner balance");

        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 totalDistributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;

        c.burn(amount); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(msg.sender) == ownerBalanceBefore - amount && c.totalSupply() == totalSupplyBefore - amount && c.totalDistributed() == totalDistributedBefore - amount);
    }

    receive() external payable {}
}

