contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        uint256 ownerBalanceBefore;
        try c.balanceOf(msg.sender) returns (uint256 __r) { ownerBalanceBefore = __r; } catch { return; }
        vm.assume(amount <= ownerBalanceBefore);
        uint256 totalSupplyBefore;
        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        uint256 totalDistributedBefore;
        try c.totalDistributed() returns (uint256 __r) { totalDistributedBefore = __r; } catch { return; }
        try c.burn(amount) {} catch { return; }
        assertTrue(c.balanceOf(msg.sender) == ownerBalanceBefore - amount && c.totalSupply() == totalSupplyBefore - amount && c.totalDistributed() == totalDistributedBefore - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
